        p.sendlineafter(b'(0/1)', b'0')
        p.sendlineafter(b'down?', str(size).encode())
        p.sendlineafter(b'Note content:', content)
        return True
    except:
        return False

def delete_note(p, idx):
    try:
        p.sendlineafter(b'>', b'2')
        p.sendlineafter(b'delete?', str(idx).encode())
        return True
    except:
        return False

def read_note(p, idx):
    try:
        p.sendlineafter(b'>', b'3')
        p.sendlineafter(b'read?', str(idx).encode())
        data = p.recvuntil(b'[1]', drop=True)
        return data
    except:
        return None

